package dev.plaintextlab.scrap

import android.content.ComponentName
import android.content.Context
import android.content.pm.PackageManager

/**
 * The name and icon under the app's launcher entry. Android fixes an app's label and icon at
 * install time, so each name/theme combination is an `<activity-alias>` in the manifest
 * (generated by android/launcher-aliases.py) and exactly one of them is enabled.
 */
object LauncherName {
    /** Must match the aliases in AndroidManifest.xml. */
    val presets = listOf("Scrap", "Notes", "Notebook", "Journal", "Wiki", "Vault", "Memo")
    private const val DEFAULT = "Scrap"

    /** Gruvbox aliases keep their original names (`.LauncherNotes`); others add the theme. */
    private fun component(context: Context, name: String, theme: ThemeName): ComponentName {
        val suffix = if (theme == ThemeName.Gruvbox) "" else theme.name
        return ComponentName(context.packageName, "dev.plaintextlab.scrap.Launcher$name$suffix")
    }

    private fun isEnabled(context: Context, name: String, theme: ThemeName): Boolean =
        when (context.packageManager.getComponentEnabledSetting(component(context, name, theme))) {
            PackageManager.COMPONENT_ENABLED_STATE_ENABLED -> true
            PackageManager.COMPONENT_ENABLED_STATE_DEFAULT -> name == DEFAULT && theme == ThemeName.Gruvbox
            else -> false
        }

    fun current(context: Context): String =
        presets.firstOrNull { name -> ThemeName.entries.any { isEnabled(context, name, it) } } ?: DEFAULT

    /** Shows [name] with [theme]'s icon in the launcher, which may take a few seconds to update. */
    fun set(context: Context, name: String, theme: ThemeName) {
        require(name in presets)
        val target = component(context, name, theme)
        if (isEnabled(context, name, theme)) return
        val pm = context.packageManager
        // Enable the new entry before disabling the old, so there's always one launcher icon.
        pm.setComponentEnabledSetting(target, PackageManager.COMPONENT_ENABLED_STATE_ENABLED, PackageManager.DONT_KILL_APP)
        for (other in presets) {
            for (t in ThemeName.entries) {
                val c = component(context, other, t)
                if (c != target && isEnabled(context, other, t)) {
                    pm.setComponentEnabledSetting(c, PackageManager.COMPONENT_ENABLED_STATE_DISABLED, PackageManager.DONT_KILL_APP)
                }
            }
        }
    }
}
